class LetterPreviewWizard(models.TransientModel):
    """
    Preview wizard for letter.template.
    - Editable HTML preview (header + body + footer rendered inline)
    - Refresh      : re-render from template
    - Print PDF    : print via QWeb report
    - Download DOCX: download as Word document
    """
    _name = 'letter.preview.wizard'
    _description = 'Letter Preview Wizard'

    # ── Inputs ────────────────────────────────────────────────────────────────
    installment_id = fields.Many2one(
        'collection.installment',
        string='Installment',
        required=True,
    )
    letter_template_id = fields.Many2one(
        'letter.template',
        string='Letter Template',
        required=True,
    )
    letter_date = fields.Date(string='Letter Date')
    letter_number = fields.Char(string='Letter Number')

    # ── Editable rendered output ──────────────────────────────────────────────
    preview_html = fields.Html(
        string='Preview',
        sanitize=False,
    )

    # ── Core render ───────────────────────────────────────────────────────────
    def _render(self):
        """Renders body sections only — no header or footer in the preview."""
        self.ensure_one()
        extra = {
            'letter_date': str(self.letter_date) if self.letter_date else '',
            'letter_number': self.letter_number or '',
        }
        # Body only — header/footer appear in PDF/DOCX output, not in preview
        parts = []
        from markupsafe import Markup
        for body in self.letter_template_id.body_ids.sorted('sequence'):
            rendered = body.render_body(
                record=self.installment_id,
                extra_values=extra,
            )
            parts.append(Markup('<div class="letter-body-section" style="margin-bottom:15px;">'))
            parts.append(rendered)
            parts.append(Markup('</div>'))
        return Markup('').join(parts)

    # ── Auto-render on field change ───────────────────────────────────────────
    @api.onchange('letter_template_id', 'installment_id', 'letter_date', 'letter_number')
    def _onchange_render_preview(self):
        if self.letter_template_id and self.installment_id:
            self.preview_html = self._render()

    # ── Refresh ───────────────────────────────────────────────────────────────
    def action_refresh_preview(self):
        self.ensure_one()
        if not self.letter_template_id or not self.installment_id:
            raise UserError(_("Please select both a Letter Template and an Installment."))
        self.preview_html = self._render()
        return {
            'type': 'ir.actions.act_window',
            'res_model': self._name,
            'res_id': self.id,
            'view_mode': 'form',
            'target': 'new',
            'context': self.env.context,
        }

    # ── Save letter helper ────────────────────────────────────────────────────
    def _save_letter(self, action):
        """
        Persist the rendered letter to letter.saved.
        action: 'pdf' or 'docx'
        """
        self.ensure_one()
        extra = {
            'letter_date': str(self.letter_date) if self.letter_date else '',
            'letter_number': self.letter_number or '',
        }
        full_html = self.letter_template_id.render_full_letter(
            record=self.installment_id,
            extra_values=extra,
        )
        collection = (
            self.installment_id.collection_id
            if self.installment_id and self.installment_id.collection_id
            else False
        )
        self.env['letter.saved'].create({
            'collection_id': collection.id if collection else False,
            'installment_id': self.installment_id.id if self.installment_id else False,
            'letter_template_id': self.letter_template_id.id,
            'letter_number': self.letter_number or '',
            'letter_date': self.letter_date,
            'action': action,
            'content_html': full_html,
        })

    # ── Save Action ───────────────────────────────────────────────────────────
    def action_save_letter(self):
        """
        Explicitly save the letter to the database.
        """
        self.ensure_one()
        if not self.letter_template_id:
            raise UserError(_("Please select a Letter Template first."))
        self._save_letter('saved')
        
        # Display a success notification and close the wizard
        return {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'type': 'success',
                'message': _("Letter saved successfully!"),
                'next': {'type': 'ir.actions.act_window_close'},
            }
        }

    # ── Print PDF ─────────────────────────────────────────────────────────────
    def action_print_pdf(self):
        """
        Print PDF using whatever is currently in the preview_html editor.
        The QWeb report reads wizard.preview_html for the body content, and
        renders the header/footer from the template's header_footer_id.

        If preview_html is empty (e.g. wizard just opened), fall back to
        rendering from the template so the PDF is never blank.
        """
        self.ensure_one()
        if not self.letter_template_id:
            raise UserError(_("Please select a Letter Template first."))

        # If the editor is empty, populate it first so the report has content
        if not self.preview_html:
            extra = {
                'letter_date': str(self.letter_date) if self.letter_date else '',
                'letter_number': self.letter_number or '',
            }
            self.preview_html = self._render()

        # Trigger the QWeb PDF report — it reads wizard.preview_html for body
        return (
            self.env.ref('letter_template.action_report_letter_preview')
            .report_action(self)
        )

    # ── Download DOCX ─────────────────────────────────────────────────────────
    def action_download_docx(self):
        """
        Build a .docx using whatever is currently in the preview_html editor
        as the body, wrapped with the real header/footer from the template.

        If preview_html is empty, fall back to rendering from the template.
        """
        self.ensure_one()
        if not self.letter_template_id:
            raise UserError(_("Please select a Letter Template first."))

        from markupsafe import Markup

        # ── Body: use the latest editor content ───────────────────────────────
        if self.preview_html:
            body_html = str(self.preview_html)
        else:
            extra = {
                'letter_date': str(self.letter_date) if self.letter_date else '',
                'letter_number': self.letter_number or '',
            }
            body_html = str(self._render())

        # ── Header / Footer: always from the template's header_footer_id ──────
        hf = self.letter_template_id.header_footer_id
        header_html = ''
        footer_html = ''

        if hf:
            # Header: logo left + html center + hr
            logo_uri = hf.get_logo_data_uri()
            logo_tag = (
                f'<img src="{logo_uri}" style="max-height:80px;width:auto;" alt="Logo"/>'
                if logo_uri else ''
            )
            center = str(hf.header_html) if hf.header_html else ''
            header_html = (
                '<div class="letter-header">'
                '<table style="width:100%;border-collapse:collapse;margin-bottom:6px;">'
                '<tr>'
                f'<td style="width:25%;text-align:left;vertical-align:middle;">{logo_tag}</td>'
                f'<td style="width:50%;text-align:center;vertical-align:middle;">{center}</td>'
                '<td style="width:25%;"></td>'
                '</tr>'
                '</table>'
                '<hr style="border:none;border-top:2px solid #000;margin:4px 0 16px 0;"/>'
                '</div>'
            )

            # Footer: hr + stamp + html
            stamp_uri = hf.get_stamp_data_uri()
            stamp_tag = (
                f'<img src="{stamp_uri}" style="max-height:80px;width:auto;" alt="Stamp"/>'
                if stamp_uri else ''
            )
            footer_content = str(hf.footer_html) if hf.footer_html else ''
            footer_html = (
                '<div class="letter-footer" style="margin-top:30px;">'
                '<hr style="border:none;border-top:2px solid #000;margin:0 0 10px 0;"/>'
                '<div style="text-align:center;">'
                + (f'<div style="margin-bottom:6px;">{stamp_tag}</div>' if stamp_tag else '')
                + (f'<div>{footer_content}</div>' if footer_content else '')
                + '</div></div>'
            )

        # ── Assemble full HTML ─────────────────────────────────────────────────
        full_html = (
            '<!DOCTYPE html><html>'
            '<head><meta charset="utf-8"/>'
            + LETTER_CSS +
            '</head><body>'
            + header_html
            + '<div class="letter-body">'
            + body_html
            + '</div>'
            + footer_html
            + '</body></html>'
        )

        # ── Package as .docx (AltChunk method) ────────────────────────────────
        docx_io = io.BytesIO()
        with zipfile.ZipFile(docx_io, 'w', zipfile.ZIP_DEFLATED) as zf:
            zf.writestr('[Content_Types].xml', (
                '<?xml version="1.0" encoding="UTF-8"?>'
                '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
                '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
                '<Default Extension="xml"  ContentType="application/xml"/>'
                '<Default Extension="htm"  ContentType="text/html"/>'
                '<Override PartName="/word/document.xml"'
                ' ContentType="application/vnd.openxmlformats-officedocument'
                '.wordprocessingml.document.main+xml"/>'
                '</Types>'
            ))
            zf.writestr('_rels/.rels', (
                '<?xml version="1.0" encoding="UTF-8"?>'
                '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
                '<Relationship Id="rId1"'
                ' Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument"'
                ' Target="word/document.xml"/>'
                '</Relationships>'
            ))
            zf.writestr('word/_rels/document.xml.rels', (
                '<?xml version="1.0" encoding="UTF-8"?>'
                '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
                '<Relationship Id="htmlChunk"'
                ' Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/aFChunk"'
                ' Target="chunk.htm"/>'
                '</Relationships>'
            ))
            zf.writestr('word/document.xml', (
                '<?xml version="1.0" encoding="UTF-8"?>'
                '<w:document'
                ' xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"'
                ' xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">'
                '<w:body><w:altChunk r:id="htmlChunk"/></w:body>'
                '</w:document>'
            ))
            zf.writestr('word/chunk.htm', full_html.encode('utf-8'))

        installment_name = (self.installment_id.name or 'letter').replace('/', '_')
        letter_num = (self.letter_number or '').replace('/', '_')
        file_name = f"Letter_{installment_name}_{letter_num}.docx".strip('_')

        attachment = self.env['ir.attachment'].sudo().create({
            'name': file_name,
            'type': 'binary',
            'datas': base64.b64encode(docx_io.getvalue()),
            'res_model': self._name,
            'res_id': self.id,
            'mimetype': (
                'application/vnd.openxmlformats-officedocument'
                '.wordprocessingml.document'
            ),
        })
        return {
            'type': 'ir.actions.act_url',
            'url': f'/web/content/{attachment.id}?download=true',
            'target': 'self',
        }
